--region public
function LimitedTimeContinuousGiftCell:RefreshCell(conf, index, currentIdx, total, cb)
    self._conf = conf
    self._index = index
    self._cb = cb

    local isFree = checkInt(conf.isFree)
    CfUtils.SetUISwitchImage(self.ImgBg, isFree == 1 and 1 or 2)
    CfUtils.SetActive(self.ImgArrow, index ~= total)
    CfUtils.RefreshCommonGoodsListLight(self.CommonGoodsListLight, conf.rewards)
    local imagePath = ActivityUtils.GetImageFullPath(conf.image)
    CfUtils.FillImage(self.ImgBgGoodsIcon, imagePath)

    if index < currentIdx then
        CfUtils.SetActive(self.BtnFree, false)
        CfUtils.SetActive(self.BtnPaid, false)
        CfUtils.SetActive(self.Finish, true)
    else
        CfUtils.SetActive(self.BtnFree, isFree == 1)
        CfUtils.SetActive(self.BtnPaid, isFree ~= 1)
        CfUtils.SetActive(self.Finish, false)
        CfUtils.SetActive(self.BtnFreeImgLock, index ~= currentIdx)
        CfUtils.SetActive(self.BtnPaidImgLock, index ~= currentIdx)
    end

    CfUtils.SetActive(self.StatusSelect1, index == currentIdx)
    CfUtils.SetActive(self.StatusSelect2, index == currentIdx)

    if isFree == 0 then
        if checkInt(conf.price) > 0 then
            -- 直充
            CfUtils.FillText(self.TextPrice, CfUtils.GetCustomDisplayPrice(conf.windowsPriceId, conf.channelProductId, 30))
            CfUtils.SetActive(self.ImgGoodsIcon, false)
        else
            -- 道具
            local prices = checkTable(conf.consume)
            local goodsId = prices[1].goodsId
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
            CfUtils.FillImage(self.ImgGoodsIcon, goodsVo.photoPath)
            CfUtils.SetActive(self.ImgGoodsIcon, true)
            CfUtils.FillText(self.TextPrice, prices[1].num)
        end
    end
    
    CfUtils.SetActive(self.UIFX_BuyGlow, false)
end

---播放购买动画
function LimitedTimeContinuousGiftCell:PlayBuyAnim()
    CfUtils.PlayAnimation(self.Root, "OverseaContinuousRechargeLimitGiftCell_BuyGlow")
end
